    "active_user_ttl": 0,
    "cache_expire": "72h",
    "cache_size": 100,
    "collaborative": {
      "early_stopping": {
        "patience": 10
      },
      "fit_epoch": 100,
      "fit_period": "60m",
      "optimize_period": "360m",
      "optimize_trials": 10,
      "type": "mf"
    },
    "context_size": 100,
    "data_source": {
      "item_ttl": 0,
      "positive_feedback_ttl": 0,
      "positive_feedback_types": [
        "star",
        "like",
        "read\u003e=3"
      ],
      "read_feedback_types": [
        "read"
      ]
    },
    "external": [
      {
        "name": "trending",
        "script": "const response = fetch(\"https://cdn.jsdelivr.net/gh/isboyjc/github-trending-api/data/daily/all.json\");\nif (!response.ok) {\n  throw new Error(`${response.status} ${response.body}`);\n}\nconst data = JSON.parse(response.body);\ndata[\"items\"].map((item) =\u003e {\n  return item[\"title\"].toLowerCase().replace(\"/\", \":\");\n})\n"
      }
    ],
    "fallback": {
      "recommenders": [
        "item-to-item/neighbors",
        "latest"
      ]
    },
    "item-to-item": [
      {
        "column": "item.Labels.embedding",
        "name": "neighbors",
        "type": "embedding"
      }
    ],
    "non-personalized": [
      {
        "filter": "(now() - item.Timestamp).Hours() \u003c 168",
        "name": "most_starred_weekly",
        "score": "count(feedback, .FeedbackType == 'star')"
      }
    ],
    "ranker": {
      "cache_expire": "120h",
      "decision_api": {
        "auth_token": "\u003creranker_auth_token\u003e",
        "instructions_template": "Would the user be interested in this repository? {{ item.Comment | replace(\",\", \" \") | replace(\"\\n\", \" \") }}",
        "model": "jev-latest",
        "state_template": "The user is interested in the following repositories:\n{% for repo in feedback -%}\n- {{ repo.Comment }}\n{% endfor -%}\n",
        "url": "https://tokenra.io/v1/decisions"
      },
      "early_stopping": {
        "patience": 10
      },
      "fit_epoch": 100,
      "fit_period": "60m",
      "optimize_period": "360m",
      "optimize_trials": 10,
      "recommenders": [
        "latest",
        "collaborative",
        "non-personalized/most_starred_weekly",
        "item-to-item/neighbors",
        "user-to-user/neighbors"
      ],
      "reranker_api": {
        "auth_token": "\u003creranker_auth_token\u003e",
        "document_template": "{{ item.Comment | replace(\",\", \" \") | replace(\"\\n\", \" \") }}",
        "model": "qwen3-rerank",
        "query_template": "You are a GitHub repository recommender system. Given a user is interested in the following repositories:\n{% for repo in feedback -%}\n- {{ repo.Comment }}\n{% endfor -%}\nPlease sort repositories by the user's interests.\n",
        "url": "\u003creranker_url\u003e"
      },
      "type": "fm"
    },
    "replacement": {
      "enable_replacement": false,
      "positive_replacement_decay": 0.8,
      "read_replacement_decay": 0.6
    },
    "search": {
      "columns": [
        "item.Comment"
      ]
    },
    "user-to-user": [
      {
        "name": "neighbors",
        "type": "items"
      }
    ]
  },
  "server": {
    "api_key": "19260817",
    "auto_insert_item": true,
    "auto_insert_user": true,
    "cache_expire": "10s",
    "clock_error": "5s",
    "default_n": 10
  },
  "tracing": {
    "collector_endpoint": "http://localhost:4317",
    "enable_tracing": false,
    "exporter": "otlp",
    "ratio": 1,
    "sampler": "always"
  }
}

